import fs from 'node:fs';
import {DatabaseSync} from 'node:sqlite';
import {createFinanceWorkspace,applyFinanceCommand} from '../../app/lib/finance-workflow-store.ts';
import {prepareFinanceCommand} from '../../app/lib/finance-workflows.ts';
import {FINANCE_SANDBOX_POLICY} from '../../app/lib/finance-sandbox-policy.ts';
import {dispatchFinanceOperation,DeterministicFinanceProvider,financeSignature,acceptFinanceWebhook,attestFinanceBank} from '../../app/lib/finance-workflow-provider.ts';
export class Statement{constructor(db,sql,args=[]){Object.assign(this,{db,sql,args});}bind(...args){return new Statement(this.db,this.sql,args);}async first(){return this.db.prepare(this.sql).get(...this.args)??null;}async all(){return {results:this.db.prepare(this.sql).all(...this.args)};}sync(){return {meta:{changes:Number(this.db.prepare(this.sql).run(...this.args).changes)}};}async run(){return this.sync();}}
export class Adapter{constructor(database){this.database=database;}prepare(sql){return new Statement(this.database,sql);}async batch(statements){this.database.exec('BEGIN IMMEDIATE');try{const result=statements.map(s=>s.sync());this.database.exec('COMMIT');return result;}catch(e){this.database.exec('ROLLBACK');throw e;}}}
export const runtime={LOKD_FINANCE_ENVIRONMENT:'sandbox',FINANCE_SIMULATOR_KEY:'isolated-fixture-signing-secret'};
export const maker={userId:'fixture-maker',email:'maker@example.test',operations:true,owner:true},reviewer={userId:'fixture-reviewer',email:'reviewer@example.test',operations:true},officer={userId:'fixture-officer',email:'officer@example.test',operations:false},client={userId:'fixture-client',email:'client@example.test',operations:false};
export const workspace='sbx-finance-cycle';
export function migration(database){if(!database.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name='finance_workspaces'").get())throw new Error('Canonical finance migration0073 is required');}
export async function setup({database,db,bookingId='FB-001',officerId='OFF-001',actors={maker,reviewer,officer,client},seed=true,policy=FINANCE_SANDBOX_POLICY}={}){
 if(!database){database=new DatabaseSync(':memory:');database.exec('PRAGMA foreign_keys=ON');for(const f of fs.readdirSync(new URL('../../drizzle',import.meta.url)).filter(f=>f.endsWith('.sql')).sort())database.exec(fs.readFileSync(new URL('../../drizzle/'+f,import.meta.url),'utf8'));}db??=new Adapter(database);migration(database);
 if(seed){database.prepare("INSERT INTO clients(id,organisation_name,contact_name,contact_email) VALUES('FC-001','Fictional company','Fixture client','client@example.test')").run();database.prepare("INSERT INTO bookings(id,client_id,site_name,site_area,post_name,service_type,minimum_grade,contract_months,start_date,end_date,shift_start,shift_end,client_price_cents,officer_rate_cents,release_cadence) VALUES(?,'FC-001','Fictional site','Fixture area','Fixture post','Specialist','Grade B',1,'2026-09-01','2026-09-30','08:00','17:00',300000,80000,'monthly')").run(bookingId);for(const [kind,id,a] of [['client','FC-001',actors.client],['officer',officerId,actors.officer]])database.prepare('INSERT INTO production_entity_links VALUES(?,?,1,?,?,?,?)').run(kind,'fixture-'+kind,a.userId,id,actors.maker.userId,new Date().toISOString());}
 await createFinanceWorkspace(db,actors.maker,runtime,workspace,policy,[['maker','preparer'],['reviewer','reviewer'],['client','client'],['officer','officer']].map(([a,role])=>({userId:actors[a].userId,role,limit:100000000})));
 let counter=0;const prepare=(command,actor=actors.maker,key='request-'+(++counter))=>prepareFinanceCommand(db,actor,runtime,workspace,command,key,policy.version),approve=c=>applyFinanceCommand(db,actors.reviewer,runtime,workspace,c.commandId,c.digest,'approved','Independently inspected fictional sources and amount'),run=async(command,actor)=>approve(await prepare(command,actor));
 const record=id=>JSON.parse(database.prepare('SELECT data_json FROM finance_current_records WHERE workspace_id=? AND id=?').get(workspace,id).data_json),balance=account=>database.prepare('SELECT balance FROM finance_balances WHERE workspace_id=? AND account=?').get(workspace,account)?.balance??0;
 const provider=new DeterministicFinanceProvider();
 async function evidence(id,status='success',{recover=false,offset=0,skipBank=false}={}){provider.status=status;await dispatchFinanceOperation(db,actors.maker,runtime,workspace,id,provider,recover);const e={...provider.result(record(id)),observedAt:new Date(Date.now()+offset).toISOString()},eventId=id+':'+record(id).attempt+':'+status+':'+(++counter);const raw=JSON.stringify({workspace,operationId:id,eventId,evidence:e});await acceptFinanceWebhook(db,runtime,raw,await financeSignature(raw,runtime.FINANCE_SIMULATOR_KEY));if(!skipBank)await attestFinanceBank(db,actors.reviewer,runtime,workspace,id,'bank:'+eventId,e);return e;}
 const settle=async(id,status='success',options)=>{await evidence(id,status,options);return run({action:'reconcile_operation',operationId:id});};
 return {db,database,bookingId,officerId,actors,prepare,approve,run,record,balance,provider,evidence,settle};
}
// Focused unit fixtures; the separate connected fixture produces service through the real handler.
export function service(x,id,company,gross,model='direct_flex'){
 const insert=(table,values)=>{const fields=x.database.prepare('PRAGMA table_info('+table+')').all();for(const f of fields)if(f.notnull&&f.dflt_value===null&&!(f.name in values))values[f.name]=f.type.toLowerCase().includes('int')?0:'fixture';const names=Object.keys(values);x.database.prepare('INSERT INTO '+table+'('+names.join(',')+') VALUES('+names.map(()=>'?').join(',')+')').run(...Object.values(values));};
 if(!x.database.prepare('SELECT id FROM workforce_employers WHERE id=?').get(company))insert('workforce_employers',{id:company,legal_name:'Fictional '+company,employer_type:model==='partner'?'partner_company':'lokd_employer'});
 insert('workforce_engagements',{id:'engagement-'+id,officer_id:x.officerId,employer_id:company,model,engagement_reference:'Fictional signed engagement'});
 insert('shifts',{id:'shift-'+id,booking_id:x.bookingId,officer_id:x.officerId});
 insert('shift_timesheets',{id,shift_id:'shift-'+id,booking_id:x.bookingId,officer_id:x.officerId,employer_id:company,workforce_engagement_id:'engagement-'+id,workforce_model:model,gross_wage_cents:gross,payable_minutes:120,service_date:'2026-09-14',operations_status:'approved_for_backend',client_evidence_status:'confirmed',environment:'test',integrity_state:'fixture'});
}
